from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    # Flood from the top and side margins. The bottom edge can close a cavity.
    seen = set()
    q = deque()
    for r in range(h):
        for c in (0, w-1):
            if grid[r][c] == bg and (r,c) not in seen:
                seen.add((r,c)); q.append((r,c))
    for c in range(w):
        if grid[0][c] == bg and (0,c) not in seen:
            seen.add((0,c)); q.append((0,c))
    while q:
        r,c = q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==bg and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==bg and (r,c) not in seen:
                out[r][c]=4
    return out

